Import ListNotations. Import AX2. Import AX2B. Import AX2S.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

Import PSMC.
(* [comment removed for export] *)
Module PSBWK.
Inductive gclass := GByte (st s' : Z) (bv : nat) | GL2L | GVis | GSetEc | GEntry | GOther.
Definition gclass_of (i k j : nat) : gclass := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S30!1+:+0!2+;+<0!2+;1+=$i;R+0$k;R+0$j;R+0-1RN$~R+1+2!2'3#3'42,5-1RN$~R+1+2!2'3#3'62,7-8RN$x;R+8+2!1'9#39-:RN$x;R!1+:2+2!2'>#3#22$p;R2-;RN$p;R!2+;1+=+2#11$p0;R1$a;R+=-;RN$p0;R!2+;+<0+2#21$st;R+<$o;R0-:RN$o;R!1+:+0+2#12$bv;R+0-=RN$a;R+=+2#4A$code;R+<$consumed;R+1,?,?,?,?$arr;R+1,?$arr;R+1,?$key;R+1,?,?$which;R+<,?,?$s';R+<$consume;R+1-1RN$consume;R+1+2#12!3,@#5#2#3,?$consume;R+1,?,?,?,?,?,?,?,?,?,?,?,?,?,A,?,B").
(* [comment removed for export] *)
Definition gclass_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto j s =>
      match gclass_of i k j with
      | GByte st s' bv => match kind_of j with KInv => true | _ => false end && (Nat.eqb j I_L || Nat.eqb j I_L2) && negb (s' =? PML.ST_STRING) && negb (s' =? PML.ST_NUMBER) &&
          negb ((9 <=? s') && (s' <=? 11)) && ((0 <=? s') && (s' <=? 255)) &&      (* [comment removed for export] *)
          match PSM2.ldelta i c ps with
          | Some (pv, _, _, _, d) =>
              let cells := SR.ps_cells ps in
              (PSM2.d_adv d + PSCW.OFF j - PSCW.OFF i =? 1) && match PSM2.d_st d with None => s' =? st | Some (ELit z) => z =? s' | _ => false end &&
              match PSM2.d_sst d, PSM2.d_nst d, PSM2.d_done d with None, None, None => true | _, _, _ => false end && negb (PSM2.d_clr d) &&
              match PSM2.d_more d with None | Some 1 => true | _ => false end &&
              (* [comment removed for export] *)
              PSM2.rng_is cells (PB4.pv_st pv) st && PSM2.rng_is cells (PB4.pv_more pv) 1 && APC.expr_vars_lt (CC.cp_nx c) (PB4.pv_wptr pv) &&
              PB.has cells (KWord (SA (PB4.pv_wptr pv) 0) 1 (EVar bv)) && PB.has cells (KRange (EVar bv) 0 255) && PB.has cells (KBlob (SA (EVar 32) 0) (EVar 33) 1) &&
              PB.prove cells (KRange (APC.esub WEND (PB4.pv_wptr pv)) 1 16384) &&
              RLF.all_bytes (fun b => negb (RLF.byte_adm bv cells b) || PSCW.all_parents (fun p => PSCW.act_eqb (PMR.dispatch st p b) (PMR.AGoto s' true)))
          | None => false end
      | GL2L => Nat.eqb j I_L &&
          match PSM2.ldelta i c ps with
          | Some (_, _, _, _, d) => (PSM2.d_adv d =? 1) && match PSM2.d_st d, PSM2.d_sst d, PSM2.d_nst d, PSM2.d_more d, PSM2.d_done d with None, None, None, None, None => true | _, _, _, _, _ => false end && negb (PSM2.d_clr d)
          | None => false end
      | GVis => Nat.eqb j I_L &&
          match PSM2.ldelta i c ps with
          | Some (pv, _, _, _, d) =>
              let cells := SR.ps_cells ps in
              (PSM2.d_adv d =? PSCW.OFF i) && match PSM2.d_sst d, PSM2.d_nst d, PSM2.d_done d with None, None, None => true | _, _, _ => false end && negb (PSM2.d_clr d) &&
              match PSM2.d_more d with Some 1 => true | _ => false end &&
              match PSM2.d_st d with Some (ELit z) => ((z =? 2) && PSM2.rng_is cells (PB4.pv_level pv) 0) || ((z =? 7) && PSM2.lo_ge cells (PB4.pv_level pv) 1) | _ => false end
          | None => false end
      | GSetEc => match kind_of j with KErr => true | _ => false end
      | GEntry => Nat.eqb j I_L0 && PSM2.foot2 c &&
          PB.has (SR.ps_cells ps) (KWord (SA Pb 220) 1 (EVar 49)) && expr_eqb (CC.esubstL GT.NF s (EVar 69)) (EVar 49) &&      (* [comment removed for export] *)
          (let cells := SR.ps_cells ps in
           (PSM2.rng_is cells (EVar 45) 0 || PSM2.lo_ge cells (EVar 42) 29) ||
           (PSM2.lo_ge cells (EVar 33) 1 && PSM2.ne_chk cells (EVar 42) 2 &&
            match PSM2.ldelta i c ps with
            | Some (_, _, _, _, d) => (PSM2.d_adv d =? 0) && match PSM2.d_st d, PSM2.d_sst d, PSM2.d_nst d, PSM2.d_more d, PSM2.d_done d with None, None, None, None, None => true | _, _, _, _, _ => false end && negb (PSM2.d_clr d)
            | None => false end))
      | GOther => false
      end
  | _ => true
  end.
Lemma gclass_ok : CH2.leaves_all G.CPS G.TAGS gclass_chk = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,C+1,D!3+E+1!3'F'G'H'I,D").
Qed.
End PSBWK.

