Module PSBW.
Abbreviation RSEGS := PML.RSEGS.
Abbreviation mem := (word -> option byte).
Abbreviation uv := PB.uv.
Section BW.
Context {SCFG_P : ScfgP}.
Variable I : PSI.inst.
Variables (eg : PMES.eghost) (M0c : mem).
Local Abbreviation L := (PSI.iL I).      Local Abbreviation HI := (PSI.iHI I).    Local Abbreviation LBo := (PSI.iLBo I).  Local Abbreviation cr := (PSI.icr I).
Local Abbreviation sp := (PSI.isp I).    Local Abbreviation r := (PSI.ir I).      Local Abbreviation P := (PSI.iP I).      Local Abbreviation V := (PSI.iV I).      Local Abbreviation E := (PSI.iE I).
Local Abbreviation B := (PSI.iB I).      Local Abbreviation kx := (PSI.kxe I eg).    Local Abbreviation bx := (PSI.ibx I).    Local Abbreviation g := (PSI.ig I).      Local Abbreviation ps := (PSI.ips I).
Local Abbreviation fx := (PSI.ifx I).    Local Abbreviation R := (PSI.iR I).      Local Abbreviation M := (PSI.iM I).      Local Abbreviation model := (PSI.imodel I).  Local Abbreviation K := (PSI.iK I).
Local Abbreviation HIok := (PSI.iHIok I).  Local Abbreviation LAY := (PSI.iLAY I).
Local Abbreviation E0 := (PSI.E0 I).     Local Abbreviation W := (PSI.W I).       Local Abbreviation Cred := (PSI.Cred I eg). Local Abbreviation XI := (PSI.XI I eg).
Local Abbreviation XIv := (PSI.XIv I eg).  Local Abbreviation LBr := (PSI.LBr I eg).  Local Abbreviation S2 := (PSI.iS2 I).  Local Abbreviation SIM := (PSI.SIM I eg).
Local Abbreviation HAMB := (CH2.heap_amb L HI GT.NF E0 M0c model LBr sp G.HDECL W G.BLS Cred).
Local Abbreviation is_leaf := (CH2.is_leaf G.CPS G.TAGS).
Let LS : hl_segs L = RSEGS := PmLayout.ly_segs L LAY.
Hypothesis OKV : CH2V.okV L M LBo sp G.HDECL W M0c.

