Definition goto_stmt (i : nat) (c : CC.cutpoint) (k : nat) (ps1 : SR.post_spec) (j : nat) (s : CC.subst) : Prop :=
  forall E1 R1 E' R' (M1 M' : mem) model1, CC.At (hl_segs L) c E1 R1 M1 -> HAMB i E1 M1 model1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
    XI i E1 M1 -> SIM i E1 M1 -> XI j (CC.env_over GT.NF s E') M' -> SIM j (CC.env_over GT.NF s E') M'.
